parameters.jsCode:
const item = $input.first().json;
let text = '';
const content = item.choices?.[0]?.message?.content || item.response || '';
try {
  const p = typeof content === 'string' ? JSON.parse(content) : content;
  text = p.reply_roman_urdu || p.urdu_alert || p.reply || p.reply_text || JSON.stringify(p);
} catch (e) {
  text = String(content) || 'Samajh nahi aaya, dobara bhej dein.';
}
return [{ json: { reply_text: text } }];
